import React, { useState, useEffect } from "react";
import { Box, Typography, Button, Card, CardContent, Grid } from "@mui/material";
import { useNavigate } from "react-router-dom";

// Mock election results (replace with dynamic data from backend)
const mockResults = [
  { position: "President", candidate: "John Doe", votes: 150 },
  { position: "Vice President", candidate: "Jane Smith", votes: 120 },
  { position: "Secretary", candidate: "Alice Johnson", votes: 90 },
];

const ResultsPage = () => {
  const navigate = useNavigate();
  const [results, setResults] = useState([]);
  const [electionEnded, setElectionEnded] = useState(false);

  // Simulate election end check (replace with actual logic)
  useEffect(() => {
    const electionEndDate = new Date("2025-03-16T00:00:00").getTime();
    const now = new Date().getTime();
    if (now > electionEndDate) {
      setElectionEnded(true);
      setResults(mockResults); // Simulate fetching results
    }
  }, []);

  return (
    <Box sx={{ textAlign: "center", p: 4 }}>
      <Typography variant="h4" fontWeight="bold" mb={4}>
        Election Results
      </Typography>

      {!electionEnded ? (
        <Box>
          <Typography variant="h6" color="text.secondary" mb={3}>
            The election has not ended yet. No results are available at this time.
          </Typography>
          <Button
            variant="contained"
            color="primary"
            onClick={() => navigate("/dashboard/vote")}
            sx={{ mt: 2, px: 4, py: 1.5, fontSize: "16px", borderRadius: "8px" }}
            aria-label="Go to Voting Page"
          >
            Go to Voting Page
          </Button>
        </Box>
      ) : results.length === 0 ? (
        <Typography variant="h6" color="text.secondary">
          No results to display.
        </Typography>
      ) : (
        <Grid container spacing={4} justifyContent="center">
          {results.map((result, index) => (
            <Grid item key={index} xs={12} sm={6} md={4}>
              <Card sx={{ 
                textAlign: "center", 
                p: 2, 
                borderRadius: "12px", 
                boxShadow: 3,
                transition: "transform 0.2s",
                "&:hover": { transform: "scale(1.05)" }
              }}>
                <CardContent>
                  <Typography variant="h6" fontWeight="bold" sx={{ mb: 2 }}>
                    {result.position}
                  </Typography>
                  <Typography variant="body1" color="text.secondary" sx={{ mb: 1 }}>
                    Winner: <strong>{result.candidate}</strong>
                  </Typography>
                  <Typography variant="body1" color="text.secondary">
                    Votes: <strong>{result.votes}</strong>
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      )}
    </Box>
  );
};

export default ResultsPage;
